DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027210359_AddProtestLog') THEN
    CREATE TABLE "Protest" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "CompetitionId" integer NOT NULL,
        "HeatId" integer NOT NULL,
        "RaceId" integer,
        "RaisedByTeamId" integer,
        "ConcernsTeamIdsJson" character varying(2000) NOT NULL,
        "RaisedByName" character varying(120),
        "Reason" character varying(1000) NOT NULL,
